CREATE VIEW public.collection_archive_records WITH (security_invoker=true) AS
SELECT 'letter'::text kind,id ref_id,archive_id identifier,title,coalesce(subtype,record_type) record_type,normalized_date sort_date,date_as_written date_text,author,recipient,origin,destination,coalesce(transcription_verified,'') body FROM public.letters WHERE record_type <> 'moved_to_gallery'
UNION ALL SELECT 'photo',id,ph_id,caption,'photograph',CASE WHEN date_year_start BETWEEN 1 AND 9999 THEN make_date(date_year_start,1,1) ELSE NULL END,date_text,people,NULL,location,NULL,coalesce(back_transcription,inscription,'') FROM public.photos
UNION ALL SELECT 'source',id,ds_id,title,source_type,normalized_date,original_date,creator,NULL,institution,NULL,coalesce(transcript,description,'') FROM public.digital_sources;
GRANT SELECT ON public.collection_archive_records TO authenticated,service_role;
CREATE TABLE public.collections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 160),description text NOT NULL DEFAULT '',created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),ai_blocked_reason text);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.collections TO authenticated; GRANT ALL ON public.collections TO service_role;
ALTER TABLE public.collections ENABLE ROW LEVEL SECURITY;
CREATE POLICY collections_read ON public.collections FOR SELECT TO authenticated USING(public.can_read_archive(auth.uid()));
CREATE POLICY collections_edit ON public.collections FOR ALL TO authenticated USING(public.can_edit_archive(auth.uid())) WITH CHECK(public.can_edit_archive(auth.uid()));
CREATE TABLE public.collection_memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),collection_id uuid NOT NULL REFERENCES public.collections(id) ON DELETE CASCADE,letter_id uuid REFERENCES public.letters(id) ON DELETE CASCADE,photo_id uuid REFERENCES public.photos(id) ON DELETE CASCADE,source_id uuid REFERENCES public.digital_sources(id) ON DELETE CASCADE,kind text GENERATED ALWAYS AS (CASE WHEN letter_id IS NOT NULL THEN 'letter' WHEN photo_id IS NOT NULL THEN 'photo' ELSE 'source' END) STORED,ref_id uuid GENERATED ALWAYS AS (coalesce(letter_id,photo_id,source_id)) STORED,created_at timestamptz NOT NULL DEFAULT now(),CHECK(num_nonnulls(letter_id,photo_id,source_id)=1),UNIQUE(collection_id,kind,ref_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.collection_memberships TO authenticated; GRANT ALL ON public.collection_memberships TO service_role;
ALTER TABLE public.collection_memberships ENABLE ROW LEVEL SECURITY;
CREATE INDEX collection_memberships_record ON public.collection_memberships(kind,ref_id);
CREATE POLICY memberships_read ON public.collection_memberships FOR SELECT TO authenticated USING(public.can_read_archive(auth.uid()) AND EXISTS(SELECT 1 FROM public.collection_archive_records r WHERE r.kind=collection_memberships.kind AND r.ref_id=collection_memberships.ref_id));
CREATE POLICY memberships_edit ON public.collection_memberships FOR ALL TO authenticated USING(public.can_edit_archive(auth.uid()) AND EXISTS(SELECT 1 FROM public.collection_archive_records r WHERE r.kind=collection_memberships.kind AND r.ref_id=collection_memberships.ref_id)) WITH CHECK(public.can_edit_archive(auth.uid()) AND EXISTS(SELECT 1 FROM public.collection_archive_records r WHERE r.kind=collection_memberships.kind AND r.ref_id=collection_memberships.ref_id));
CREATE TABLE public.collection_suggestions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),collection_id uuid NOT NULL REFERENCES public.collections(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('letter','photo','source')),ref_id uuid NOT NULL,reason text NOT NULL,excerpt text NOT NULL DEFAULT '',confidence text NOT NULL CHECK(confidence IN ('High','Medium','Low')),dismissed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(collection_id,kind,ref_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.collection_suggestions TO authenticated; GRANT ALL ON public.collection_suggestions TO service_role;
ALTER TABLE public.collection_suggestions ENABLE ROW LEVEL SECURITY;
CREATE POLICY suggestions_read ON public.collection_suggestions FOR SELECT TO authenticated USING(public.can_read_archive(auth.uid()) AND EXISTS(SELECT 1 FROM public.collection_archive_records r WHERE r.kind=collection_suggestions.kind AND r.ref_id=collection_suggestions.ref_id));
CREATE POLICY suggestions_edit ON public.collection_suggestions FOR ALL TO authenticated USING(public.can_edit_archive(auth.uid()) AND EXISTS(SELECT 1 FROM public.collection_archive_records r WHERE r.kind=collection_suggestions.kind AND r.ref_id=collection_suggestions.ref_id)) WITH CHECK(public.can_edit_archive(auth.uid()) AND EXISTS(SELECT 1 FROM public.collection_archive_records r WHERE r.kind=collection_suggestions.kind AND r.ref_id=collection_suggestions.ref_id));
CREATE FUNCTION public.touch_collection() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='collections' THEN NEW.updated_at=now(); RETURN NEW; END IF; UPDATE public.collections SET updated_at=now() WHERE id=coalesce(NEW.collection_id,OLD.collection_id); RETURN coalesce(NEW,OLD); END $$;
REVOKE ALL ON FUNCTION public.touch_collection() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.touch_collection() TO authenticated,service_role;
CREATE TRIGGER collections_touch BEFORE UPDATE ON public.collections FOR EACH ROW EXECUTE FUNCTION public.touch_collection();
CREATE TRIGGER memberships_touch AFTER INSERT OR DELETE ON public.collection_memberships FOR EACH ROW EXECUTE FUNCTION public.touch_collection();